'use client'

/**
 * IntelligenceFeed — events generated by the signal engine for meaningful
 * transitions only. Each event links to the explainability drawer.
 */

import { BrainCircuit, ChevronRight } from 'lucide-react'
import { formatClock, type IntelEvent } from '@/lib/engine'

const KIND_LABEL: Record<IntelEvent['kind'], string> = {
  'SIGNAL CHANGE': 'SIGNAL CHANGE',
  'TWIN STATE': 'TWIN STATE',
  RECOVERY: 'RECOVERY',
  SYSTEM: 'SYSTEM',
  DEMO: 'DEMO',
}

export function IntelligenceFeed({
  events,
  onExplain,
  onOpenHistory,
}: {
  events: IntelEvent[]
  onExplain: (event: IntelEvent) => void
  onOpenHistory: () => void
}) {
  return (
    <article id="intelligence" className="panel intelligence-panel">
      <div className="panel-heading">
        <span>INTELLIGENCE FEED</span>
        <span className="feed-count">
          <BrainCircuit /> {events.length} EVENT{events.length === 1 ? '' : 'S'}
        </span>
      </div>

      <div className="event-list">
        {events.slice(0, 6).map((event, index) => (
          <button
            className={`event-row sev-${event.severity} ${index === 0 ? 'event-new' : ''}`}
            key={event.id}
            onClick={() => onExplain(event)}
          >
            <span className="event-time">{formatClock(event.time)}</span>
            <b className={`event-kind kind-${event.severity}`}>{KIND_LABEL[event.kind]}</b>
            <span className="event-title">{event.title}</span>
            <span className="event-why">
              WHY AM I SEEING THIS? <ChevronRight />
            </span>
          </button>
        ))}
        {events.length === 0 && <p className="feed-empty">No meaningful changes yet. Your twin is watching quietly.</p>}
      </div>

      <button className="text-button" onClick={onOpenHistory}>
        VIEW FULL HISTORY <ChevronRight />
      </button>
    </article>
  )
}
